#!/usr/bin/env node
/**
 * Quality gate: Dateigröße (CONTRACT §6)
 * -------------------------------------------------------------------------
 * Ziel:   ≤ 400 Zeilen je handgeschriebener Quelldatei  (weiches Ziel, WARNUNG)
 * Maximum: 550 Zeilen je handgeschriebener Quelldatei  (hartes Limit, FEHLER)
 *
 * Maßgeblich ist die physische Zeilenzahl (identisch zu `wc -l`).
 *
 * Umfang: alle `*.ts`- und `*.tsx`-Dateien unter `src/` (handgeschrieben).
 *
 * Ausnahmen (dokumentiert und begründet):
 *
 *  1. Generierte Dateien werden ignoriert. Erkannt am Kopfkommentar
 *     (`auto-generated`, `generated by`, `do not edit`, `@generated`).
 *     Betroffen: `src/data/songs/index.ts` — erzeugt von
 *     `scripts/migrate_and_deduplicate.py`; die Datei darf nicht von Hand
 *     gepflegt werden und ist damit nicht reviewbar.
 *
 *  2. Bekannte Altlasten über dem harten Limit. Diese Dateien überschreiten
 *     550 Zeilen bereits vor Einführung des Gates; sie sind in
 *     `ARCHITECTURE.md` §6.1 und in `REQUIREMENTS.md` (NFR-009 / GAP-007)
 *     als offener Rückstand dokumentiert. Solange das Refactoring nicht
 *     umgesetzt ist, blockieren sie den Merge nicht — das Gate meldet sie
 *     aber bei jedem Lauf sichtbar. **Wächst** eine Ausnahme-Datei über
 *     den hier hinterlegten Stand hinaus, meldet das Gate eine Warnung.
 *     Jede *neue* Datei über 550 Zeilen ist dagegen ein harter Fehler.
 *
 * Ausgabe: Datei, Zeilenzahl, Grenze, Verstoß. Exit-Code 1 bei Fehler.
 *
 * Toleranz gegenüber laufender Parallelarbeit:
 *   - Dateien, die während des Laufs verschwinden, werden übersprungen
 *   - Lesefehler werden als Befund gemeldet, nicht als Absturz
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(SCRIPT_DIR, '..');
const SRC_DIR = path.join(REPO_ROOT, 'src');

/** Weiches Ziel: darüber Warnung. */
const SOFT_LIMIT = 400;
/** Hartes Maximum: darüber Fehler (Exit 1). */
const HARD_LIMIT = 550;

/**
 * Bekannte Altlasten über dem harten Limit (ARCHITECTURE.md §6.1,
 * REQUIREMENTS.md NFR-009 / GAP-007). Wert = Stand bei Einführung des Gates.
 * @type {Record<string, {lines: number, reason: string}>}
 */
const SIZE_EXCEPTIONS = {
  'src/utils/validate-song-data.ts': {
    lines: 502,
    reason:
      'Schema- und Grenzwertprüfung (GAP-007): in Schema-, Grenzwert- und ' +
      'Katalogprüfung zerlegen',
  },
  'src/app/admin/review/page.tsx': {
    lines: 755,
    reason: 'Admin-Review-Seite (GAP-007): zerlegt in Songliste + Editor',
  },
  'src/app/lobby/page.tsx': {
    lines: 744,
    reason: 'Lobby-Seite (GAP-007): zerlegt in Lobby, Spielerliste, Moduswahl',
  },
  'src/components/game/RevealPhase.tsx': {
    lines: 671,
    reason: 'Reveal-Phase (GAP-007): Logik und Darstellung trennen',
  },
  'src/stores/game-store.ts': {
    lines: 640,
    reason: 'Zustands-Store (GAP-007): in Teil-Stores zerlegen',
  },
  'src/components/game/MusicPlayer.tsx': {
    lines: 630,
    reason: 'MusicPlayer (GAP-007): Provider-Adapter auslagern',
  },
  'src/components/game/modes/TimelineMode.tsx': {
    lines: 579,
    reason: 'Timeline-Modus (GAP-007): Modus-Logik und UI trennen',
  },
  'src/app/browse/page.tsx': {
    lines: 572,
    reason: 'Browse-Seite (GAP-007): Suchfeld, Liste und Filter trennen',
  },
};

/** Marker, die eine generierte Datei kennzeichnen. */
const GENERATED_MARKERS = [
  /auto-?generated/i,
  /generated by/i,
  /do not edit/i,
  /@generated/i,
  /code generated/i,
];

/** Verzeichnisse, die nicht durchsucht werden. */
const IGNORED_DIRS = new Set([
  'node_modules',
  '.next',
  'coverage',
  'out',
  '.git',
]);

/**
 * @param {string} dir
 * @param {string[]} [out]
 * @returns {string[]}
 */
function collectSourceFiles(dir, out = []) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (IGNORED_DIRS.has(entry.name)) continue;
      collectSourceFiles(full, out);
    } else if (entry.isFile() && /\.tsx?$/.test(entry.name)) {
      out.push(full);
    }
  }
  return out;
}

/**
 * Zählt die physischen Zeilen (identisch zu `wc -l`).
 * @param {string} content
 * @returns {number}
 */
export function countLines(content) {
  if (content === '') return 0;
  const parts = content.split(/\r?\n/);
  return parts[parts.length - 1] === '' ? parts.length - 1 : parts.length;
}

/**
 * Prüft, ob eine Datei generiert ist (Kopfkommentar).
 * @param {string} content
 * @returns {boolean}
 */
export function isGenerated(content) {
  const head = content.slice(0, 2000);
  return GENERATED_MARKERS.some((marker) => marker.test(head));
}

/**
 * Führt den Gate-Lauf aus.
 * @returns {{
 *   files: number,
 *   generated: {file: string, lines: number}[],
 *   warnings: {file: string, lines: number, text: string}[],
 *   errors: {file: string, lines: number, text: string}[],
 *   notes: string[],
 *   ioErrors: string[]
 * }}
 */
export function runFileSizeCheck() {
  const files = collectSourceFiles(SRC_DIR);
  const generated = [];
  const warnings = [];
  const errors = [];
  const notes = [];
  const ioErrors = [];

  let checked = 0;

  for (const absolute of files) {
    const relative = path
      .relative(REPO_ROOT, absolute)
      .split(path.sep)
      .join('/');
    let content;
    try {
      content = fs.readFileSync(absolute, 'utf8');
    } catch (error) {
      ioErrors.push(
        `${relative}: Datei nicht lesbar (${error.code ?? error.message})`
      );
      continue;
    }

    const lines = countLines(content);
    checked += 1;

    if (isGenerated(content)) {
      generated.push({ file: relative, lines });
      continue;
    }

    const exception = SIZE_EXCEPTIONS[relative];

    if (lines > HARD_LIMIT) {
      if (exception) {
        // Bekannte Altlast: sichtbar melden, aber nicht blockieren (siehe Kopf).
        const delta = lines - exception.lines;
        notes.push(
          `${relative}: ${lines} Zeilen — bekannte Altlast über ${HARD_LIMIT} ` +
            `(Ausnahme, Refactoring offen: ${exception.reason})` +
            (delta === 0
              ? ' — Stand unverändert'
              : ` — ${delta > 0 ? '+' : ''}${delta} Zeilen gegenüber dem Ausnahme-Stand (${exception.lines})`)
        );
        if (delta > 0) {
          warnings.push({
            file: relative,
            lines,
            text:
              `über dem harten Limit (${HARD_LIMIT}) und ${delta} Zeilen mehr als der ` +
              `hinterlegte Ausnahme-Stand (${exception.lines}) — Rückstand wächst, ` +
              `Refactoring offen: ${exception.reason}`,
          });
        }
      } else {
        errors.push({
          file: relative,
          lines,
          text: `über dem harten Limit (${HARD_LIMIT}) um ${lines - HARD_LIMIT} Zeilen`,
        });
      }
      continue;
    }

    if (lines > SOFT_LIMIT) {
      warnings.push({
        file: relative,
        lines,
        text: `über dem weichen Ziel (${SOFT_LIMIT}) um ${lines - SOFT_LIMIT} Zeilen`,
      });
    }
  }

  // Ausnahmen, die nicht mehr existieren oder geschrumpft sind
  const seen = new Set(
    files.map((f) => path.relative(REPO_ROOT, f).split(path.sep).join('/'))
  );
  for (const [file, exception] of Object.entries(SIZE_EXCEPTIONS)) {
    if (!seen.has(file)) {
      notes.push(
        `${file}: Ausnahme-Eintrag ist veraltet (Datei existiert nicht mehr).`
      );
    }
  }

  return { files: checked, generated, warnings, errors, notes, ioErrors };
}

// Nur ausfuehren, wenn die Datei direkt als CLI gestartet wurde.
const invokedDirectly =
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);

if (invokedDirectly) {
  const result = runFileSizeCheck();

  console.log('Phomu Qualitätsgate: Dateigröße');
  console.log(`Geprüfte Quelldateien unter src/: ${result.files}`);
  console.log(
    `Grenzen: Ziel ${SOFT_LIMIT} Zeilen (Warnung), Maximum ${HARD_LIMIT} Zeilen (Fehler)`
  );

  if (result.generated.length > 0) {
    console.log(`\nÜbersprungen (generiert): ${result.generated.length}`);
    for (const gen of result.generated) {
      console.log(`   ${gen.file} (${gen.lines} Zeilen, generiert)`);
    }
  }

  if (result.notes.length > 0) {
    console.log(
      `\nBekannte Altlasten (dokumentierte Ausnahmen): ${result.notes.length}`
    );
    for (const note of result.notes) {
      console.log(`   ${note}`);
    }
  }

  if (result.warnings.length > 0) {
    console.log(`\n⚠️  ${result.warnings.length} Warnung(en):`);
    for (const warning of result.warnings) {
      console.log(
        `   ${warning.file}: ${warning.lines} Zeilen — ${warning.text}`
      );
    }
  }

  if (result.ioErrors.length > 0) {
    console.log(`\n⚠️  ${result.ioErrors.length} Lesefehler:`);
    for (const ioError of result.ioErrors) {
      console.log(`   ${ioError}`);
    }
  }

  if (result.errors.length > 0) {
    console.error(
      `\n❌ ${result.errors.length} Fehler (über dem Maximum von ${HARD_LIMIT} Zeilen):`
    );
    for (const error of result.errors) {
      console.error(`   ${error.file}: ${error.lines} Zeilen — ${error.text}`);
    }
    process.exit(1);
  }

  console.log(
    `\n✅ Gate bestanden — 0 Fehler, ${result.warnings.length} Warnung(en), ` +
      `${result.notes.length} bekannte Altlast(en).`
  );
  process.exit(0);
}
